document.querySelector('#apply')?.addEventListener('click',()=>{const v=document.querySelector('#category').value;document.querySelectorAll('.rooms article').forEach(x=>x.hidden=v!=='all'&&x.dataset.cat!==v)});document.querySelector('#reset')?.addEventListener('click',()=>{document.querySelector('#category').value='all';document.querySelectorAll('.rooms article').forEach(x=>x.hidden=false)});